int last_state = HIGH;
int stable_state = HIGH;
unsigned long last_change = 0;
void setup() { pinMode({{btn_pin}}, INPUT_PULLUP); Serial.begin(115200); }
void loop() {
    int r = digitalRead({{btn_pin}});
    if (r != last_state) { last_change = millis(); last_state = r; }
    if (millis() - last_change > {{debounce_ms}} && r != stable_state) {
        stable_state = r;
        if (stable_state == LOW) Serial.println("pressed");
    }
}
